@Test
public void testSplitNormal() {
    Assert.assertArrayEquals(new String[] { "a", "b", "c", "d" }, StringUtils.splitCsv("a|b|c|d", '|', null, null));
    Assert.assertArrayEquals(new String[] { "", "a", "b", "c", "d" }, StringUtils.splitCsv("|a|b|c|d", '|', null, null));
    Assert.assertArrayEquals(new String[] { "a", "b", "c", "d", "" }, StringUtils.splitCsv("a|b|c|d|", '|', null, null));
    Assert.assertArrayEquals(new String[] { "a", "b|c", "d" }, StringUtils.splitCsv("a|b\\|c|d", '|', '\\', null));
    Assert.assertArrayEquals(new String[] { "a", "b\\", "c", "d" }, StringUtils.splitCsv("a|b\\\\|c|d", '|', '\\', null));
    Assert.assertArrayEquals(new String[] { "a", "b|c", "d" }, StringUtils.splitCsv("a|\"b|c\"|d", '|', '\\', '\"'));
    Assert.assertArrayEquals(new String[] { "a", "|b|c|", "d" }, StringUtils.splitCsv("a|\"|b|c|\"|d", '|', '\\', '\"'));
    Assert.assertArrayEquals(new String[] { "a", "b\\c", "d" }, StringUtils.splitCsv("a|\"b\\c\"|d", '|', '\\', '\"'));
    Assert.assertArrayEquals(new String[] { "a", "\"b", "c\"", "d" }, StringUtils.splitCsv("a|\\\"b|c\\\"|d", '|', '\\', '\"'));
}

