    String jsonStr = "{\"code\":0,\"errMsg\":\"OK\",\"data\":" + "[{\"brokerId\":136,\"brokerIp\":\"127.0.0.1\"," + "\"brokerPort\":8123,\"manageStatus\":\"online\"," + "\"runStatus\":\"notRegister\",\"subStatus\":\"processing_event\"," + "\"stepOp\":32,\"isConfChanged\":\"true\",\"isConfLoaded\":\"false\"," + "\"isBrokerOnline\":\"false\",\"brokerVersion\":\"-\"," + "\"acceptPublish\":\"false\",\"acceptSubscribe\":\"false\"}]}";
    TubeHttpBrokerInfoList brokerInfoList = gson.fromJson(jsonStr, TubeHttpBrokerInfoList.class);
    Assert.assertEquals(1, brokerInfoList.getData().size());
    Assert.assertEquals(0, brokerInfoList.getCode());
    Assert.assertEquals("OK", brokerInfoList.getErrMsg());
    Assert.assertTrue(brokerInfoList.getData().get(0).isConfChanged());
    Assert.assertFalse(brokerInfoList.getData().get(0).isAcceptPublish());
    Assert.assertFalse(brokerInfoList.getData().get(0).isBrokerOnline());
}

